const r = ($input.first().json.report) || {};
const totals = r.totals || {total:0,active:0,completed:0,archived:0};
const phases = Array.isArray(r.phase_counts) ? r.phase_counts : [];
const stale = Array.isArray(r.stale_projects) ? r.stale_projects : [];
const recent = Array.isArray(r.recent_completed) ? r.recent_completed : [];
const agents = Array.isArray(r.agent_activity_7d) ? r.agent_activity_7d : [];
const avgDays = r.avg_days_completed || null;

function esc(s) { return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }
function dateShort(s) { if (!s) return '-'; return new Date(s).toISOString().substring(0,10); }

const maxN = phases.reduce((m,p) => Math.max(m, Number(p.n||0)), 0) || 1;

const phaseRows = phases.map(p => {
  const pct = Math.round((Number(p.n||0) / maxN) * 100);
  const w = Math.max(pct, 2);
  const isTerminal = (p.phase === 'completed' || p.phase === 'archived');
  const barColor = isTerminal ? '#888' : '#3b82f6';
  return `<tr>
    <td>${esc(p.label)} <span style="color:#aaa;font-size:11px">${esc(p.phase)}</span></td>
    <td style="text-align:right;font-weight:600">${p.n}</td>
    <td><div style="background:#f0f0f3;height:14px;border-radius:7px;overflow:hidden"><div style="background:${barColor};height:100%;width:${w}%"></div></div></td>
  </tr>`;
}).join('');

const staleRows = stale.length ? stale.map(s => {
  const cls = s.days_stale > 30 ? ' style="background:#fee"' : '';
  return `<tr${cls}>
    <td>${esc(s.name)}</td><td>${esc(s.client_name)}</td>
    <td>${esc(s.current_phase)}</td>
    <td style="text-align:right;font-weight:600">${s.days_stale}d</td>
  </tr>`;
}).join('') : '<tr><td colspan="4" style="text-align:center;color:#888;padding:18px">Sin proyectos estancados &gt;14d (estado saludable)</td></tr>';

const recentRows = recent.length ? recent.map(c => `<tr>
  <td>${esc(c.name)}</td><td>${esc(c.client_name)}</td>
  <td>${dateShort(c.completed_at)}</td>
  <td style="text-align:right">${c.total_days}d</td>
</tr>`).join('') : '<tr><td colspan="4" style="text-align:center;color:#888;padding:18px">Sin proyectos completados todavia</td></tr>';

const agentRows = agents.length ? agents.map(a => {
  const errCls = (Number(a.failures||0) > 0) ? ' style="color:#c00;font-weight:600"' : '';
  return `<tr>
    <td>${esc(a.agent_name)}</td>
    <td style="text-align:right">${a.runs}</td>
    <td style="text-align:right"${errCls}>${a.failures}</td>
  </tr>`;
}).join('') : '<tr><td colspan="3" style="text-align:center;color:#888;padding:14px">Sin ejecuciones en los ultimos 7 dias</td></tr>';

const html = `<!DOCTYPE html>
<html lang="es">
<head><meta charset="utf-8"><title>Pipeline Metrics - ArquitAI</title>
<style>
  body{font-family:system-ui,sans-serif;max-width:1200px;margin:32px auto;padding:0 20px;color:#222;background:#f7f7f8}
  h1{margin:0 0 8px}
  .sub{color:#888;font-size:13px;margin-bottom:24px}
  h2{margin:32px 0 12px;font-size:18px;border-bottom:1px solid #ddd;padding-bottom:6px}
  .cards{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:24px}
  .card{background:#fff;border:1px solid #ddd;border-radius:8px;padding:16px}
  .card h3{margin:0 0 6px;font-size:12px;color:#666;text-transform:uppercase;letter-spacing:.5px}
  .card .v{font-size:26px;font-weight:600}
  table{width:100%;border-collapse:collapse;background:#fff;border:1px solid #ddd;border-radius:8px;overflow:hidden}
  th,td{padding:8px 12px;border-bottom:1px solid #eee;font-size:14px;text-align:left;vertical-align:middle}
  th{background:#f0f0f3;font-weight:600;font-size:12px;text-transform:uppercase;color:#555}
  tr:last-child td{border-bottom:none}
  .meta{font-size:12px;color:#888;margin-top:24px}
  .row-grid{display:grid;grid-template-columns:1.4fr 1fr;gap:18px}
  @media (max-width: 900px) { .row-grid{grid-template-columns:1fr} .cards{grid-template-columns:repeat(2,1fr)} }
</style></head>
<body>
<h1>Pipeline Metrics - ArquitAI</h1>
<p class="sub">Distribucion de proyectos por fase + atascos detectados + actividad de agentes (7d).</p>
<div class="cards">
  <div class="card"><h3>Total proyectos</h3><div class="v">${totals.total}</div></div>
  <div class="card"><h3>Activos</h3><div class="v">${totals.active}</div></div>
  <div class="card"><h3>Completados</h3><div class="v">${totals.completed}</div></div>
  <div class="card"><h3>Tiempo medio</h3><div class="v">${avgDays != null ? avgDays + 'd' : 'N/A'}</div></div>
</div>
<div class="row-grid">
  <div>
    <h2>Distribucion por fase</h2>
    <table>
      <thead><tr><th>fase</th><th style="text-align:right">n</th><th>distribucion</th></tr></thead>
      <tbody>${phaseRows}</tbody>
    </table>
  </div>
  <div>
    <h2>Actividad de agentes (7d)</h2>
    <table>
      <thead><tr><th>agent</th><th style="text-align:right">runs</th><th style="text-align:right">fail</th></tr></thead>
      <tbody>${agentRows}</tbody>
    </table>
  </div>
</div>
<h2>Proyectos estancados (>14d sin movimiento)</h2>
<table>
  <thead><tr><th>proyecto</th><th>cliente</th><th>fase</th><th style="text-align:right">dias</th></tr></thead>
  <tbody>${staleRows}</tbody>
</table>
<h2>Ultimos completados</h2>
<table>
  <thead><tr><th>proyecto</th><th>cliente</th><th>completado</th><th style="text-align:right">total</th></tr></thead>
  <tbody>${recentRows}</tbody>
</table>
<div class="meta">Generado ${new Date().toISOString()} - fuente: tabla projects + activity_log + agent_executions</div>
</body></html>`;

return [{ json: { html } }];
